+			return path
+		}
+		if !filepath.IsAbs(target) {
+			target = filepath.Join(filepath.Dir(path), target)
+		}
+		if target == prev {
+			// A self-referential link (a -> a): the kernel answers ELOOP at
+			// once, so stop here instead of re-walking it to the hop cap.
+			return path
+		}
+		path = target
+	}
