```go
package repopolicy

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
)

// WorktreeRegistryRelative is the git-common-dir subtree holding per-worktree
// runtime data for globally tracked repositories.
const WorktreeRegistryRelative = "entire/worktree"

// RuntimeDir returns the git-common runtime directory for one worktree.
func RuntimeDir(repository Repository) string {
	return filepath.Join(repository.GitCommonDir, WorktreeRegistryRelative, repository.WorktreeKey)
}

var repoSettingsFiles = []string{"settings.json", "settings.local.json"}

// ReadRepoActivation reads the repository's own settings files. It is the
// leaf-level twin of settings.IsSetUpAndEnabled: a project settings.json
// (default enabled) or a settings.local.json with an explicit "enabled" key
// counts as repo-level configuration; the local value wins. Malformed JSON
// or a non-boolean "enabled" is an error so callers fail closed.
func ReadRepoActivation(worktreeRoot string) (RepoActivation, error) {
	var activation RepoActivation
	for i, name := range repoSettingsFiles {
		path := filepath.Join(worktreeRoot, ".entire", name) // entire-join-ok: repo configuration lives in the literal worktree, never runtime-routed
		data, err := os.ReadFile(path)                       //nolint:gosec // fixed repo-relative configuration path
		if errors.Is(err, fs.ErrNotExist) {
			continue
		}
		if err != nil {
			return RepoActivation{}, fmt.Errorf("reading %s: %w", path, err)
		}
		enabled, err := enabledFromSettingsData(data)
		if err != nil {
			return RepoActivation{}, fmt.Errorf("%s: %w", path, err)
		}
		isProject := i == 0
		if isProject || enabled != nil {
			activation.Configured = true
		}
		switch {
		case enabled != nil:
			activation.Enabled = *enabled
		case isProject:
			activation.Enabled = true // main's default: a project file without the key is enabled
		}
	}
	return activation, nil
}

func enabledFromSettingsData(data []byte) (*bool, error) {
	var raw map[string]json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil {
		return nil, fmt.Errorf("parsing settings: %w", err)
	}
	value, ok := raw["enabled"]
	if !ok || bytes.Equal(bytes.TrimSpace(value), []byte("null")) {
		return nil, nil //nolint:nilnil // nil means the optional enabled field is absent
	}
	var enabled bool
	if err := json.Unmarshal(value, &enabled); err != nil {
		return nil, errors.New("enabled must be a boolean")
	}
	return &enabled, nil
}
```

- [ ] **Step 3: Rewrite `policy.go`**

```go
package repopolicy

import "context"

// ClassifyRepoPolicy resolves one read-only repository-policy snapshot for
// the current directory. It never writes.
func ClassifyRepoPolicy(ctx context.Context) (RepoPolicy, error) {
	return ClassifyRepoPolicyAt(ctx, ".")
}

// ClassifyRepoPolicyAt classifies an explicit worktree. Precedence:
//
//  1. The repository's own settings files (repo-level activation). A
//     configured repo is active iff enabled — an explicit enabled:false is a
//     veto that also blocks the global tier.
//  2. Otherwise the user-global tier: enabled, valid, and not excluding this
//     repo. Any error there fails closed (inactive + the error).
//
// Trust (checkpoint egress) is decided last from the same inputs.
func ClassifyRepoPolicyAt(ctx context.Context, dir string) (RepoPolicy, error) {
	repository, err := ResolveRepositoryAt(ctx, dir)
	if err != nil {
		return inactiveGlobalPolicy(InactiveReasonGlobalOff), err
	}
	policy := RepoPolicy{
		ActivationSource: ActivationInactive,
		InactiveReason:   InactiveReasonGlobalOff,
		WorktreeRoot:     repository.WorktreeRoot,
		GitCommonDir:     repository.GitCommonDir,
		WorktreeKey:      repository.WorktreeKey,
	}
	userSettings, err := LoadUserSettings(ctx)
	if err != nil {
		return policy, err
	}

	activation, err := ReadRepoActivation(repository.WorktreeRoot)
	if err != nil {
		policy.InactiveReason = InactiveReasonRepoDisabled
		return policy, err
	}
	switch {
	case activation.Configured && activation.Enabled:
		policy.Active = true
		policy.ActivationSource = ActivationLocal
		policy.InactiveReason = InactiveReasonNone
	case activation.Configured:
		policy.InactiveReason = InactiveReasonRepoDisabled
	default:
		global, classifyErr := ClassifyGlobalConfig(ctx, userSettings.Global, func(context.Context) (Repository, error) {
			return repository, nil
		})
		policy.Active = global.Active
		policy.ActivationSource = global.ActivationSource
		policy.InactiveReason = global.InactiveReason
		if classifyErr != nil {
			policy.Trust = DecideEgress(ctx, policy, userSettings.Global, repository)
			return policy, classifyErr
		}
	}
	policy.Trust = DecideEgress(ctx, policy, userSettings.Global, repository)
	return policy, nil
}

type repoPolicyContextKey struct{}

// WithRepoPolicy returns a context carrying an immutable policy snapshot.
func WithRepoPolicy(ctx context.Context, policy RepoPolicy) context.Context {
	return context.WithValue(ctx, repoPolicyContextKey{}, policy)
}

// RepoPolicyFromContext returns a policy snapshot previously attached to ctx.
func RepoPolicyFromContext(ctx context.Context) (RepoPolicy, bool) {
	policy, ok := ctx.Value(repoPolicyContextKey{}).(RepoPolicy)
	return policy, ok
}
```

