// primaryRefStamp marks that this worktree's primary metadata ref has been
// ensured once. It lives in the (git-side) runtime root, so it is never a
// worktree file, and it exists only to keep the per-hook cost at a stat:
// EnsurePrimaryRefTo opens the repository and may talk to remotes.
const primaryRefStamp = "primary-ref-ready"

// MaybeEnsureGlobalSetup performs lazy, invisible per-worktree setup for a
// globally tracked repo: installs the git hooks (skipped when core.hooksPath
// resolves inside the worktree) and ensures the checkpoint metadata ref.
// Everything it writes lives inside .git/. Best-effort by contract: every
// failure logs at Debug and returns — a lazy-enable failure must never break
// the user's commit or agent session. Git-hook presence is re-checked on
// every hook (a file read), so hooks a user deleted come back on the next
// activity without any marker bookkeeping.
func MaybeEnsureGlobalSetup(ctx context.Context) {
	logCtx := logging.WithComponent(ctx, "global-setup")
	policy, ok := repopolicy.RepoPolicyFromContext(ctx)
	if !ok {
		var err error
		if policy, err = repopolicy.ClassifyRepoPolicy(ctx); err != nil {
			logging.Debug(logCtx, "global lazy setup: policy unavailable", slog.String("error", err.Error()))
			return
		}
	}
	if !policy.Active || policy.ActivationSource != repopolicy.ActivationGlobal {
		return
	}
	if !IsGitHookInstalled(ctx) {
		worktreeResident, hooksDir, resolveErr := HooksDirIsWorktreeResident(ctx)
		switch {
		case resolveErr != nil:
			logging.Debug(logCtx, "global lazy setup: cannot resolve hooks dir", slog.String("error", resolveErr.Error()))
			return
		case worktreeResident:
			logging.Debug(logCtx, "global lazy setup: hooks dir inside worktree; skipping git hook install", slog.String("hooks_dir", hooksDir))
		default:
			if _, err := installGitHooks(ctx, true, hookSettingsFromConfig(ctx), io.Discard); err != nil {
				logging.Debug(logCtx, "global lazy setup: git hook install failed", slog.String("error", err.Error()))
				return
			}
		}
	}
	stamp := filepath.Join(policy.RuntimeRoot(), primaryRefStamp)
	if _, err := os.Stat(stamp); err == nil {
		return
	}
	repo, err := OpenRepository(ctx)
	if err != nil {
		logging.Debug(logCtx, "global lazy setup: open repository failed", slog.String("error", err.Error()))
		return
	}
	defer repo.Close()
	if err := EnsurePrimaryRefTo(ctx, repo, io.Discard); err != nil {
		logging.Debug(logCtx, "global lazy setup: ensure primary metadata ref failed", slog.String("error", err.Error()))
		return
	}
	if err := os.MkdirAll(filepath.Dir(stamp), 0o700); err == nil {
		_ = os.WriteFile(stamp, nil, 0o600) //nolint:errcheck // a missing stamp only costs a repeat ensure next hook
	}
	logging.Debug(logCtx, "global lazy setup completed")
}
```

