// recordEnableTrust records checkpoint-egress trust for a repo the user just
// explicitly enabled. Only meaningful once the global tier is configured:
// from then on every active repo needs trust in the user settings file
// before its checkpoints leave the machine, and running `entire enable`
// here IS that consent. Best-effort — enable never fails because of it.
func recordEnableTrust(ctx context.Context, w io.Writer) {
	us, err := settings.LoadUserSettings(ctx)
	if err != nil || !us.GlobalConfigured() {
		return
	}
	id, err := settings.TrustCurrentRepo(ctx)
	if err != nil {
		fmt.Fprintf(w, "Note: could not record checkpoint-sync trust for this repo (%v); run 'entire trust' or answer the prompt on your next push.\n", err)
		return
	}
	if !settings.CheckpointEgressAllowed(ctx) {
		return // already covered by trust_all or an existing entry — nothing to announce
	}
	fmt.Fprintf(w, "✓ Trusted %s for checkpoint sync (global tracking is on)\n", id.DisplayScope())
}
```

Call it after the successful settings save in `runEnableInteractive`, `setupAgentHooksNonInteractive`, and `runEnable` (the re-enable path). Note `CheckpointEgressAllowed` classifies fresh (no policy in ctx on these foreground paths) so it reflects the write.

