	TrustSourceNone  = repopolicy.TrustSourceNone
	TrustSourceLocal = repopolicy.TrustSourceLocal
	TrustSourceAll   = repopolicy.TrustSourceAll
	TrustSourceRepo  = repopolicy.TrustSourceRepo
