	}
	codex := globalTrustBannerSuffix(ctx, agent.AgentNameCodex)
	if !strings.HasPrefix(codex, " Entire") || strings.Contains(codex, "\n") {
		t.Fatalf("codex suffix must be single-line with a space prefix, got %q", codex)
