	writeUserSettings(t, `{"global":{"enabled":true,"trusted_origins":["github.com/acme/widgets"]}}`)
	if got := globalTrustBannerSuffix(ctx, agent.AgentNameClaudeCode); got != "" {
		t.Fatalf("trusted repo must not get the banner, got %q", got)
